SELECT CASE WHEN s.browser IN ('Safari', 'Edge') THEN 'priority' ELSE 'other' END AS browser_group, SUM(CASE WHEN we.page = '/checkout' THEN we.duration_sec ELSE 0 END) AS checkout_duration_sec FROM web_events we LEFT JOIN sessions s ON we.session_id = s.id WHERE we.session_id IN (17, 20, 26) GROUP BY CASE WHEN s.browser IN ('Safari', 'Edge') THEN 'priority' ELSE 'other' END ORDER BY checkout_duration_sec DESC;
